"""Keep browser language recognition identical to the collector's exact labels."""
import json
from pathlib import Path
from language_names import LABELS

ROOT = Path(__file__).resolve().parents[1]

if __name__ == '__main__':
    (ROOT / 'static/language-labels.js').write_text(
        '// Generated by scripts/export_language_labels.py from language_names.LABELS.\n'
        + 'export const LANGUAGE_LABELS = ' + json.dumps(LABELS, ensure_ascii=False, indent=2) + ';\n')
